from pathlib import Path
p=Path('frontend/src/knowledge.ts');s=p.read_text(encoding='utf-8')
s=s.replace('For stainless steel, use the specific grades/designations and limits in the current IS 2347 text and amendments; do not choose a generic “food-grade steel” label as a substitute.','For a stainless-steel cooker body/lid/container/grid, Amendment No. 2 (May 2025) lists grades X04Cr19Ni9/X07Cr18Ni9 to IS 5522/IS 6911, or X8Cr16Mn8Cu2Ni2N to IS 15997/IS 6911. It also lists aluminium designations under IS 21/IS 737. The amendment caps each listed toxic metal (lead, cadmium, arsenic) at 0.05%. Verify the complete material clause and component-specific exceptions in the current standard.')
s=s.replace('The exact raw-material grades, construction, tests and marking depend on the chosen material and the current manual’s Annex A. If you mean a cooking/serving container rather than a bottle, see IS 14756 instead.','For stainless-steel bottle body, the June 2025 manual lists Grade N1/N2 to IS 15997 or IS 6911, Grade 304 series to IS 5522 or IS 6911, or 316/316L to IS 6911; minimum bottle sheet thickness is 0.4 mm (lid/cap 0.4 mm). O-rings/washers: food-grade silicone to IS 3565. For cooking/serving containers, use IS 14756 instead.')
p.write_text(s,encoding='utf-8')
p=Path('data/standards.json');s=p.read_text(encoding='utf-8')
s=s.replace('Body/lid/container/grid: material requirements are in IS 2347 Clause 5.1; the 2025 product manual scope lists aluminium alloy, stainless steel, or 3-ply construction.','Body/lid/container/grid: Clause 5.1.1, as amended May 2025, lists aluminium designations 19000, 19500, 19000A, 19002, 31000, 31000A, 31200, 40800, 81400, 81400A to IS 21/IS 737; or stainless designations X04Cr19Ni9/X07Cr18Ni9 to IS 5522/IS 6911 or X8Cr16Mn8Cu2Ni2N to IS 15997/IS 6911. Amendment note caps each listed toxic metal (lead, cadmium, arsenic) at 0.05%. Verify full clause scope/exclusions in the current standard.')
s=s.replace('The product manual identifies copper, stainless steel and aluminium as body-material categories.','Body material may be copper, stainless steel or aluminium. For stainless steel the June 2025 BIS product manual lists Grade N1/N2 to IS 15997 or IS 6911, Grade 304 series to IS 5522 or IS 6911, or 316/316L to IS 6911; minimum bottle-body sheet thickness is 0.4 mm and lid/cap thickness is 0.4 mm. O-rings/washers use food-grade silicone to IS 3565.')
p.write_text(s,encoding='utf-8')
